# generated by gen_portable.py from dcsvet_core.py -- do not edit by hand
"""DCSVET core: shared features, labels and the lift-vector low-level pilot.

The same 26-double observation (combat_v3 ICD) is used on both sides:
  * offline, dcsvet_data.py rebuilds it from DCS export trajectories;
  * online, the JSBSim arena hands it to the red opponent every 60 Hz tick.
So features() is the single definition of what the cloned policy sees.

Control representation (what we clone): the lift vector, i.e. the aerodynamic specific force
perpendicular to the velocity, expressed in the velocity frame
  e_v    = velocity direction
  e_up   = world-up projected perpendicular to e_v      (wings-level lift direction)
  e_side = e_v x e_up                                   (right wing for upright flight, NED)
as (n_up, n_side) in g, plus a speed target. This is attitude-singularity free and lets the
pilot loop, roll and pull through the vertical, which the Euler roll/pitch command() cannot.
"""
import math
import numpy as np

G0 = 9.80665
FT = .3048
FPS_TO_KT = 1 / 1.6878098571011957
UP = np.array([0., 0., -1.])                   # NED


def wrap180(x):
    return (x + 180.) % 360. - 180.


def dcm_body_to_ned(phi, theta, psi):
    """Columns are body x, y, z axes expressed in NED (angles in rad)."""
    cp, sp, ct, st, cy, sy = math.cos(phi), math.sin(phi), math.cos(theta), math.sin(theta), math.cos(psi), math.sin(psi)
    ned_to_body = np.array([[ct * cy, ct * sy, -st],
                            [sp * st * cy - cp * sy, sp * st * sy + cp * cy, sp * ct],
                            [cp * st * cy + sp * sy, cp * st * sy - sp * cy, cp * ct]])
    return ned_to_body.T


def vel_frame(v):
    """(e_v, e_up, e_side, ok). ok=False when flying (almost) straight up/down."""
    V = float(np.linalg.norm(v))
    ev = v / max(V, 1e-6)
    up = UP - float(np.dot(UP, ev)) * ev
    n = float(np.linalg.norm(up))
    ok = n > .12
    if not ok:                                    # near vertical: fall back to body-agnostic north reference
        ref = np.array([1., 0., 0.])
        up = ref - float(np.dot(ref, ev)) * ev
        n = float(np.linalg.norm(up))
    eu = up / max(n, 1e-9)
    es = np.cross(ev, eu)
    return ev, eu, es, ok


def isa(h_m):
    T = 288.15 - .0065 * min(h_m, 11000.)
    p = 101325. * (T / 288.15) ** 5.25588
    if h_m > 11000.:
        p *= math.exp(-G0 * (h_m - 11000.) / (287.053 * 216.65))
    return T, p


def tas_to_cas(tas, h_m):
    """m/s TAS -> m/s CAS (ISA, subsonic compressible)."""
    T, p = isa(h_m)
    a = math.sqrt(1.4 * 287.053 * T)
    M = tas / a
    qc = p * ((1 + .2 * M * M) ** 3.5 - 1)
    a0, p0 = 340.294, 101325.
    return a0 * math.sqrt(5 * ((qc / p0 + 1) ** (2 / 7) - 1))


def rel_ned(o):
    lat, lat2 = math.radians(o[0]), math.radians(o[20])
    return np.array([(lat2 - lat) * 6378137., math.radians(o[21] - o[1]) * 6378137. * math.cos((lat + lat2) / 2),
                     -(o[22] - o[2]) * FT])


def body_up_mu(phi, theta, psi, ev, eu, es):
    """Bank of the body lift axis (-z_body) around the velocity vector, deg (+ = right)."""
    zb = dcm_body_to_ned(phi, theta, psi)[:, 2]
    upb = -zb
    return math.degrees(math.atan2(float(np.dot(upb, es)), float(np.dot(upb, eu))))


N_FEAT = 24


def features(o):
    """26-double OBS -> N_FEAT float32 features in the own velocity frame."""
    o = np.asarray(o, dtype=np.float64)
    v = o[6:9] * FT
    ve = o[23:26] * FT
    V = max(float(np.linalg.norm(v)), 50.)
    ev, eu, es, ok = vel_frame(v)
    rel = rel_ned(o)
    r = max(float(np.linalg.norm(rel)), 1.)
    l = rel / r
    rv = ve - v
    w_los = np.cross(rel, rv) / (r * r)                       # LOS rotation rate, rad/s
    Ve = float(np.linalg.norm(ve))
    aspect = math.acos(float(np.clip(np.dot(ve, -rel) / max(Ve * r, 1e-6), -1, 1))) if Ve > 1 else math.pi
    ata = math.acos(float(np.clip(np.dot(ev, l), -1, 1)))
    closing = -float(np.dot(rel, rv)) / r
    phi, theta, psi = np.radians(o[3:6])
    mu = math.radians(body_up_mu(phi, theta, psi, ev, eu, es))
    gamma = math.asin(float(np.clip(-ev[2], -1, 1)))
    alt = o[2] * FT
    f = [
        math.log(r / 1000.), r / 3000.,
        float(np.dot(l, ev)), float(np.dot(l, eu)), float(np.dot(l, es)),
        float(np.dot(ve, ev)) / V, float(np.dot(ve, eu)) / V, float(np.dot(ve, es)) / V,
        float(np.dot(w_los, ev)) * 5., float(np.dot(w_los, eu)) * 5., float(np.dot(w_los, es)) * 5.,
        ata / math.pi, aspect / math.pi, closing / 200.,
        V / 250., Ve / 250., math.sin(gamma), math.cos(gamma) if ok else 0.,
        math.sin(mu), math.cos(mu), float(np.clip(o[18], -20, 40)) / 20.,
        alt / 5000., (o[22] - o[2]) * FT / 2000., float(ok),
    ]
    return np.asarray(f, dtype=np.float32)


class LiftPilot:
    """Low-level: track lift-vector bank mu (deg, about velocity), load factor n (g) and CAS (kt).
    Same actuator limits / slew as the frozen RepairController; ground and energy recovery kept."""

    def __init__(self, floor_m=1200., gains=None):
        # rec_v2 (2026-10-27): ground recovery pulls corner-speed G at idle when fast and diving (old: 4.5 g at full
        # power -> a split-S chase at 470 kt accelerated to 730 kt and hit the ground).  0 = old behaviour exactly.
        g = dict(k_mu=.045, k_p=.005, k_n=.08, k_ni=.15, k_ff=.12, n_max=8.6, rec_v2=0.)
        if gains:
            g.update(gains)
        self.g = g
        self.floor = floor_m
        self.last = np.array([0., 0., 0., .8])
        self.ni = 0.
        self.si = 0.
        self.recovering = False
        self.mode = 'lift'

    def n_meas(self, o):
        # Sign-robust load factor.  Local JSBSim gives n-pilot-z-norm = -1 in level flight (negative when pulling);
        # the official Host packet carries it POSITIVE when pulling (+5 at 5 g, measured 2026-10-26).  Using the
        # magnitude works for both; it only misreads genuine negative-g, which this pilot never commands.
        return abs(float(o[14]))

    def command(self, o, mu_t, n_t, cas_t):
        o = np.asarray(o, dtype=np.float64)
        g = self.g
        alt, down = o[2] * FT, o[8] * FT
        cas = o[12] * FPS_TO_KT
        v = o[6:9] * FT
        ev, eu, es, ok = vel_frame(v)
        phi, theta, psi = np.radians(o[3:6])
        mu = body_up_mu(phi, theta, psi, ev, eu, es)
        self.mode = 'lift'
        guard = False
        if alt < self.floor or (down > 30 and (alt - self.floor) / down < 6):
            self.recovering = True
        if self.recovering and alt > self.floor + 400 and down <= 0 and cas > 220:
            self.recovering = False
        rec_idle = False
        if self.recovering:
            # roll the lift vector to the sky and pull
            mu_t, n_t, cas_t, guard = 0., 4.5, 400., True
            self.mode = 'recover'
            if g['rec_v2']:
                n_t = float(np.clip(3. + (cas - 250.) / 80. * 5.6, 4.5, g['n_max']))
                rec_idle = cas > 420. and down > 0.
        elif cas < 170 or o[18] > 24:
            mu_t, n_t, cas_t, guard = mu, .6, 420., True
            self.mode = 'energy'
        n_t = float(np.clip(n_t, -1.5, g['n_max']))
        if n_t < .35 and not guard:                      # unloaded: lift direction meaningless, hold roll
            err = 0.
        else:
            err = wrap180(mu_t - mu)
        p_deg = math.degrees(o[9])
        aileron = g['k_mu'] * err - g['k_p'] * p_deg
        if abs(err) > 100 and not guard:                 # far off: roll first, do not pull the wrong way
            n_t = min(n_t, 1.)
        nm = self.n_meas(o)
        self.ni = float(np.clip(self.ni + g['k_ni'] * (n_t - nm) / 60., -.6, .6))
        q_deg = math.degrees(o[10])
        elevator = -(g['k_n'] * (n_t - nm) + g['k_ff'] * (n_t - 1.) + self.ni)
        if nm > 8.8:
            elevator = max(elevator, -.05)
        self.si = float(np.clip(self.si + .0004 * (cas_t - cas) / 60, -.5, .35))
        throttle = .65 + .008 * (cas_t - cas) + self.si
        if guard:
            throttle, self.si = (0. if rec_idle else 1.), 0.
        target = np.clip([aileron, elevator, 0., throttle], [-1, -1, -1, 0], [1, 1, 1, 1])
        self.last += np.clip(target - self.last, [-.12, -.08, -.06, -.025], [.12, .08, .06, .025])
        self.telemetry = dict(mu=mu, mu_t=mu_t, n=nm, n_t=n_t, cas=cas, cas_t=cas_t, mode=self.mode)
        return self.last.copy(), guard


def lift_to_cmd(n_up, n_side):
    return math.degrees(math.atan2(n_side, n_up)), math.hypot(n_up, n_side)
